01', '8', etc.)\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        parts = re.split(r'\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\s{2,}|\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\t+', line)  # Split on 2+ spaces or tabs\\\\\\\\\\\\\\\\n        if len(parts) >= 2:\\\\\\\\\\\\\\\\n            # Check which end is the code\\\\\\\\\\\\\\\\n            potential_code = parts[-1].strip()\\\\\\\\\\\\\\\\n            potential_label = ' '.join(parts[:-1]).strip()\\\\\\\\\\\\\\\\n            \\\\\\\\\\\\\\\\n            # If last part looks like a code (digits, short), it's likely: Label CODE\\\\\\\\\\\\\\\\n            if re.match(r'^[0-9]+[A-Z]?$|^[A-Z]+$', potential_code) and potential_label:\\\\\\\\\\\\\\\\n                value_labels[potential_code] = potential_label\\\\\\\\\\\\\\\\n            else:\\\\\\\\\\\\\\\\n                # Try first part as code\\\\\\\\\\\\\\\\n                potential_code = parts[0].strip()\\\\\\\\\\\\\\\\n                potential_label = ' '.join(parts[1:]).strip()\\\\\\\\\\\\\\\\n                if re.match(r'^[0-9]+$|^[0-9]+[A-Z]?$', potential_code) and potential_label:\\\\\\\\\\\\\\\\n                    value_labels[potential_code] = potential_label\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    return question, value_labels\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef get_unique_values(df, var_name):\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Get unique non-null values from a column, sorted.\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    if var_name not in df.columns:\\\\\\\\\\\\\\\\n        return []\\\\\\\\\\\\\\\\n    col = df[var_name].dropna()\\\\\\\\\\\\\\\\n    unique = sorted(col.unique())\\\\\\\\\\\\\\\\n    return unique\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef infer_type(var_name, unique_values, has_labels):\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"I