          # No labels found anywhere; try to infer from unique data values\\\\\\\\\\\\\\\\n                unique_vals = get_unique_values(df, var_name)\\\\\\\\\\\\\\\\n                if unique_vals and len(unique_vals) <= 25:\\\\\\\\\\\\\\\\n                    # Create null-valued entries for categorical\\\\\\\\\\\\\\\\n                    values = {str(v): None for v in unique_vals}\\\\\\\\\\\\\\\\n                    labels_source = \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"data_inferred\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n                    labels_null += 1\\\\\\\\\\\\\\\\n                else:\\\\\\\\\\\\\\\\n                    labels_null += 1\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        # Infer type\\\\\\\\\\\\\\\\n        var_type = infer_type(var_name, get_unique_values(df, var_name), bool(values))\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        # Build variable entry\\\\\\\\\\\\\\\\n        var_entry = {\\\\\\\\\\\\\\\\n            \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"question\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": question,\\\\\\\\\\\\\\\\n            \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"type\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": var_type,\\\\\\\\\\\\\\\\n            \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"values\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": values\\\\\\\\\\\\\\\\n        }\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        # Add notes if skip patterns exist (simplified check)\\\\\\\\\\\\\\\\n        notes = \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n        if \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"=>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" in question:\\\\\\\\\\\\\\\\n            notes = \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Contains skip patterns (see raw codebook)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        if notes:\\\\\\\\\\\\\\\\n            var_entry[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"notes\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"] = notes\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        codebook[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"variables\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"][var_name] = var_entry\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    return codebook, labels_from_sav, labels_from_md, labels_null\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef main():\\\\\\\\\\\\\\\\n    print(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Loading SAV metadata...\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    sav_meta = load_sav_metadata()\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    print(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Loading Markdown documentation...\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    md_content = load_markdown()\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    print(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Building codebook...\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    codebook, lfs, lfm, lnull = build_codebook(sav_meta, md_content)\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Variables with labels from SAV: {lfs}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Variables with labels from Markdown: {lfm}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Variables with null/inferred labels: {lnull}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Total variables: {len(codebook['variables'])}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    # Write output\\\\\\\\\\\\\\\\n    output_path = Path(OUTPUT_FILE)\\\\\\\\\\\\\\\\n    output_path.parent.mkdir(parents=True, exist_ok=True)\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    with open(output_path, 'w', encoding='utf-8') as f:\\\\\\\\\\\\\\\\n        json.dump(codebook, f, indent=2, ensure_ascii=False)\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\nWrote: {output_path}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    # Verify by reading first few variables\\\\\\\\\\\\\\\\n    print(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n=== SAMPLE (first 3 variables) ===\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    for i, (var_name, var_data) in enumerate(list(codebook['variables'].items())[:3]):\\\\\\\\\\\\\\\\n        print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n{var_name}:\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n        print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Question: {var_data['question'][:80]}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n        print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Type: {var_data['type']}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n        print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Values: {list(var_data['values'].items())[:3]}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nif __name__ == '__main__':\\\\\\\\\\\\\\\\n    main()\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\",\\\\\\\\n              \\\\\\\\\\\\\\\"after\\\\\\\\\\\\\\\": \\\\\\\\\\\\\\\"#!/usr/bin/env python3\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\nGenerate codebook.json for eeq_2007 by merging SAV metadata with markdown codebook.\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nStrategy:\\\\\\\\\\\\\\\\n1. Load SAV metadata: variable names, labels (questions), and value labels\\\\\\\\\\\\\\\\n2. Load markdown codebook and extract code→label mappings\\\\\\\\\\\\\\\\n3. For each variable:\\\\\\\\\\\\\\\\n   - Use SAV question text if available\\\\\\\\\\\\\\\\n   - Use SAV value labels if they exist\\\\\\\\\\\\\\\\n   - If SAV has no labels but variable is categorical, search markdown\\\\\\\\\\\\\\\\n   - If no labels found anywhere, leave values as {}\\\\\\\\\\\\\\\\n4. Write codebook.json\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nimport json\\\\\\\\\\\\\\\\nimport re\\\\\\\\\\\\\\\\nfrom pathlib import Path\\\\\\\\\\\\\\\\nimport pyreadstat\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\n# Paths\\\\\\\\\\\\\\\\nSAV_FILE = Path(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"/home/hubcad25/opubliq/repos/survey-cleaner/_SharedFolder_data_produit/eeq_2007/Quebec Election Study 2007 (SPSS).sav\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\nMD_FILE = Path(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"/tmp/eeq_2007_fr_codebook.md\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\nOUTPUT_DIR = Path(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"/home/hubcad25/opubliq/repos/survey-cleaner/surveys/eeq_2007\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\nOUTPUT_FILE = OUTPUT_DIR / \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"codebook.json\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef load_sav_metadata():\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Load variable names, labels, and value labels from SAV file.\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    df, meta = pyreadstat.read_sav(SAV_FILE)\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    return {\\\\\\\\\\\\\\\\n        'column_names': list(meta.column_names),\\\\\\\\\\\\\\\\n        'column_labels': list(meta.column_labels),\\\\\\\\\\\\\\\\n        'variable_value_labels': meta.variable_value_labels,\\\\\\\\\\\\\\\\n        'df': df\\\\\\\\\\\\\\\\n    }\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef load_markdown():\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Parse markdown file to extract variable definitions and value labels.\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    with open(MARKDOWN_FILE, 'r', encoding='utf-8', errors='ignore') as f:\\\\\\\\\\\\\\\\n        content = f.read()\\\\\\\\\\\\\\\\n    return content\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef parse_markdown_for_variable(var_name, md_content):\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    Extract question text and value labels for a specific variable from markdown.\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    Pattern:\\\\\\\\\\\\\\\\n    VARNAME:\\\\\\\\\\\\\\\\n    Question text...\\\\\\\\\\\\\\\\n    Code1    Label\\\\\\\\\\\\\\\\n    Code2    Label\\\\\\\\\\\\\\\\n    ...\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    # Create regex to find the variable block\\\\\\\\\\\\\\\\n    # Match: VAR_NAME: ... until next variable or EOF\\\\\\\\\\\\\\\\n    pattern = rf'^{re.escape(var_name.upper())}:\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\s*\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n(.*?)(?=^[A-Z][A-Z0-9]*:\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\s*\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n|\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\Z)'\\\\\\\\\\\\\\\\n    match = re.search(pattern, md_content, re.MULTILINE | re.IGNORECASE | re.DOTALL)\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    if not match:\\\\\\\\\\\\\\\\n        return None, {}\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    block = match.group(1)\\\\\\\\\\\\\\\\n    lines = block.strip().split('\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n')\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    # First non-empty line is usually the question\\\\\\\\\\\\\\\\n    question = None\\\\\\\\\\\\\\\\n    value_labels = {}\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    i = 0\\\\\\\\\\\\\\\\n    for line in lines:\\\\\\\\\\\\\\\\n        line = line.strip()\\\\\\\\\\\\\\\\n        if not line:\\\\\\\\\\\\\\\\n            continue\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        # If we haven't found the question yet, this is it\\\\\\\\\\\\\\\\n        if question is None:\\\\\\\\\\\\\\\\n            question = line\\\\\\\\\\\\\\\\n            i += 1\\\\\\\\\\\\\\\\n            break\\\\\\\\\\\\\\\\n        i += 1\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    # Now parse value labels (code + label pairs)\\\\\\\\\\\\\\\\n    # Format: \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Label    Code\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" or \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Code    Label\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" or similar\\\\\\\\\\\\\\\\n    for line in lines[i:]:\\\\\\\\\\\\\\\\n        line = line.strip()\\\\\\\\\\\\\\\\n        if not line or line.startswith('=>'):\\\\\\\\\\\\\\\\n            continue\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        # Try to split: look for multiple spaces or tabs\\\\\\\\\\\\\\\\n        # The pattern is usually: \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Text description    CODE\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" or \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"CODE    Text\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n        # We need to find where the code is (usually numeric or short like '1', '01', '8', etc.)\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        parts = re.split(r'\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\s{2,}|\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\t+', line)  # Split on 2+ spaces or tabs\\\\\\\\\\\\\\\\n        if len(parts) >= 2:\\\\\\\\\\\\\\\\n            # Check which end is the code\\\\\\\\\\\\\\\\n            potential_code = parts[-1].strip()\\\\\\\\\\\\\\\\n            potential_label = ' '.join(parts[:-1]).strip()\\\\\\\\\\\\\\\\n            \\\\\\\\\\\\\\\\n            # If last part looks like a code (digits, short), it's likely: Label CODE\\\\\\\\\\\\\\\\n            if re.match(r'^[0-9]+[A-Z]?$|^[A-Z]+$', potential_code) and potential_label:\\\\\\\\\\\\\\\\n                value_labels[potential_code] = potential_label\\\\\\\\\\\\\\\\n            else:\\\\\\\\\\\\\\\\n                # Try first part as code\\\\\\\\\\\\\\\\n                potential_code = parts[0].strip()\\\\\\\\\\\\\\\\n                potential_label = ' '.join(parts[1:]).strip()\\\\\\\\\\\\\\\\n                if re.match(r'^[0-9]+$|^[0-9]+[A-Z]?$', potential_code) and potential_label:\\\\\\\\\\\\\\\\n                    value_labels[potential_code] = potential_label\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    return question, value_labels\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef get_unique_values(df, var_name):\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Get unique non-null values from a column, sorted.\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    if var_name not in df.columns:\\\\\\\\\\\\\\\\n        return []\\\\\\\\\\\\\\\\n    col = df[var_name].dropna()\\\\\\\\\\\\\\\\n    unique = sorted(col.unique())\\\\\\\\\\\\\\\\n    return unique\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef infer_type(var_name, unique_values, has_labels):\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Infer variable type based on unique values and labels.\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    if not unique_values:\\\\\\\\\\\\\\\\n        return \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"text\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    # If has labels or few unique values, it's categorical\\\\\\\\\\\\\\\\n    if has_labels or len(unique_values) <= 25:\\\\\\\\\\\\\\\\n        return \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"categorical\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    # If numeric with many values, continuous\\\\\\\\\\\\\\\\n    try:\\\\\\\\\\\\\\\\n        for v in unique_values:\\\\\\\\\\\\\\\\n            float(v)\\\\\\\\\\\\\\\\n        return \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"continuous\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    except (ValueError, TypeError):\\\\\\\\\\\\\\\\n        return \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"text\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef build_codebook(sav_meta, md_content):\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Build codebook by merging SAV and Markdown sources.\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    codebook = {\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"survey_id\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"eeq_2007\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"variables\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": {}\\\\\\\\\\\\\\\\n    }\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    var_names = sav_meta['column_names']\\\\\\\\\\\\\\\\n    col_labels = sav_meta['column_labels']\\\\\\\\\\\\\\\\n    var_value_labels = sav_meta['variable_value_labels']\\\\\\\\\\\\\\\\n    df = sav_meta['df']\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    labels_from_sav = 0\\\\\\\\\\\\\\\\n    labels_from_md = 0\\\\\\\\\\\\\\\\n    labels_null = 0\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    for i, var_name in enumerate(var_names):\\\\\\\\\\\\\\\\n        # Get question text from SAV column_labels (indexed by position)\\\\\\\\\\\\\\\\n        question = col_labels[i] if i < len(col_labels) else \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        # If not in SAV or empty, try markdown\\\\\\\\\\\\\\\\n        if not question:\\\\\\\\\\\\\\\\n            question, _ = parse_markdown_for_variable(var_name, md_content)\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        # Skip if no question text found\\\\\\\\\\\\\\\\n        if not question:\\\\\\\\\\\\\\\\n            continue\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        # Determine value labels: SAV first, then markdown\\\\\\\\\\\\\\\\n        values = {}\\\\\\\\\\\\\\\\n        labels_source = None\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        # Check if SAV has value labels for this variable\\\\\\\\\\\\\\\\n        sav_labels = var_value_labels.get(var_name, {})\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        if sav_labels:\\\\\\\\\\\\\\\\n            # Use SAV labels directly\\\\\\\\\\\\\\\\n            values = dict(sav_labels)\\\\\\\\\\\\\\\\n            labels_source = \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"sav\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n            labels_from_sav += 1\\\\\\\\\\\\\\\\n        else:\\\\\\\\\\\\\\\\n            # Try to get labels from markdown\\\\\\\\\\\\\\\\n            _, md_labels = parse_markdown_for_variable(var_name, md_content)\\\\\\\\\\\\\\\\n            \\\\\\\\\\\\\\\\n            if md_labels:\\\\\\\\\\\\\\\\n                values = md_labels\\\\\\\\\\\\\\\\n                labels_source = \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"markdown\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n                labels_from_md += 1\\\\\\\\\\\\\\\\n            else:\\\\\\\\\\\\\\\\n                # No labels found anywhere; try to infer from unique data values\\\\\\\\\\\\\\\\n                unique_vals = get_unique_values(df, var_name)\\\\\\\\\\\\\\\\n                if unique_vals and len(unique_vals) <= 25:\\\\\\\\\\\\\\\\n                    # Create null-valued entries for categorical\\\\\\\\\\\\\\\\n                    values = {str(v): None for v in unique_vals}\\\\\\\\\\\\\\\\n                    labels_source = \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"data_inferred\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n                    labels_null += 1\\\\\\\\\\\\\\\\n                else:\\\\\\\\\\\\\\\\n                    labels_null += 1\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        # Infer type\\\\\\\\\\\\\\\\n        var_type = infer_type(var_name, get_unique_values(df, var_name), bool(values))\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        # Build variable entry\\\\\\\\\\\\\\\\n        var_entry = {\\\\\\\\\\\\\\\\n            \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"question\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": question,\\\\\\\\\\\\\\\\n            \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"type\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": var_type,\\\\\\\\\\\\\\\\n            \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"values\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\": values\\\\\\\\\\\\\\\\n        }\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        # Add notes if skip patterns exist (simplified check)\\\\\\\\\\\\\\\\n        notes = \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n        if \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"=>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" in question:\\\\\\\\\\\\\\\\n            notes = \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Contains skip patterns (see raw codebook)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        if notes:\\\\\\\\\\\\\\\\n            var_entry[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"notes\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"] = notes\\\\\\\\\\\\\\\\n        \\\\\\\\\\\\\\\\n        codebook[\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"variables\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"][var_name] = var_entry\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    return codebook, labels_from_sav, labels_from_md, labels_null\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\ndef main():\\\\\\\\\\\\\\\\n    print(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Loading SAV metadata...\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    sav_meta = load_sav_metadata()\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    print(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Loading Markdown documentation...\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    md_content = load_markdown()\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    print(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"Building codebook...\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    codebook, lfs, lfm, lnull = build_codebook(sav_meta, md_content)\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Variables with labels from SAV: {lfs}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Variables with labels from Markdown: {lfm}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Variables with null/inferred labels: {lnull}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Total variables: {len(codebook['variables'])}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    # Write output\\\\\\\\\\\\\\\\n    output_path = Path(OUTPUT_FILE)\\\\\\\\\\\\\\\\n    output_path.parent.mkdir(parents=True, exist_ok=True)\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    with open(output_path, 'w', encoding='utf-8') as f:\\\\\\\\\\\\\\\\n        json.dump(codebook, f, indent=2, ensure_ascii=False)\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\nWrote: {output_path}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    \\\\\\\\\\\\\\\\n    # Verify by reading first few variables\\\\\\\\\\\\\\\\n    print(\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n=== SAMPLE (first 3 variables) ===\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n    for i, (var_name, var_data) in enumerate(list(codebook['variables'].items())[:3]):\\\\\\\\\\\\\\\\n        print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n{var_name}:\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n        print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Question: {var_data['question'][:80]}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n        print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Type: {var_data['type']}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n        print(f\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"  Values: {list(var_data['values'].items())[:3]}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\")\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\nif __name__ == '__main__':\\\\\\\\\\\\\\\\n    main()\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\",\\\\\\\\n              \\\\\\\\\\\\\\\"additions\\\\\\\\\\\\\\\": 18,\\\\\\\\n              \\\\\\\\\\\\\\\"deletions\\\\\\\\\\\\\\\": 7,\\\\\\\\n              \\\\\\\\\\\\\\\"status\\\\\\\\\\\\\\\": \\\\\\\\\\\\\\\"modified\\\\\\\\\\\\\\\"\\\\\\\\n            },\\\\\\\\n            {\\\\\\\\n         